import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { Fournisseur } from 'src/app/models/Fournisseur';
import { Medicament } from 'src/app/models/Medicament';
import { FournisseurService } from 'src/app/services/fournisseur.service';

@Component({
  selector: 'app-fournisseur-detail',
  templateUrl: './fournisseur-detail.component.html',
  styleUrls: ['./fournisseur-detail.component.css']
})
export class FournisseurDetailComponent implements OnInit {
  fournisseur: Fournisseur | undefined;
  medicaments: Medicament[] = [];

  constructor(
    private route: ActivatedRoute,
    private fournisseurService: FournisseurService
  ) {}

  ngOnInit(): void {
    const idFournisseurString = this.route.snapshot.paramMap.get('id');

    // Check if idFournisseur is valid and is a number
    const idFournisseur = idFournisseurString ? Number(idFournisseurString) : NaN;

    // If idFournisseur is valid (not NaN), proceed with the API call
    if (!isNaN(idFournisseur)) {
      // Fetch all medicaments for the given fournisseur
      this.fournisseurService.getMedicamentsByFournisseur(idFournisseur).subscribe(data => {
        this.medicaments = data;

        // If we have medicaments, we assume the fournisseur ID is the same for all
        if (this.medicaments.length > 0) {
          const fournisseurId = this.medicaments[0].idfournisseur;  // Assuming that each medicament has a `idfournisseur`

          // Now fetch the fournisseur details using the `fournisseurId`
          this.fournisseurService.getFournisseurById(fournisseurId).subscribe(fournisseurData => {
            this.fournisseur = fournisseurData;
          });
        }
      });
    } else {
      console.error('Invalid fournisseur ID');
    }
  }
}
